// Parse OpenAI JSON response and filter
const items = [];

for (const item of $input.all()) {
  try {
    let response = item.json.text || item.json.message?.content || item.json;

    // Extract JSON if wrapped in markdown code blocks
    if (typeof response === 'string') {
      const jsonMatch = response.match(/```json\s*([\s\S]*?)```/) || response.match(/\[\s*{[\s\S]*}\s*\]/);
      if (jsonMatch) {
        response = jsonMatch[1] || jsonMatch[0];
      }
      response = JSON.parse(response);
    }

    // Handle both array and single object responses
    const jobs = Array.isArray(response) ? response : [response];

    for (const job of jobs) {
      // Get minimum score threshold
      const minScore = $('Set: CV Text & Config').item.json.min_relevance_score || 0.7;

      if (job.passed === true && job.score >= minScore) {
        // Merge with original job data
        const originalJob = $('Scrape LinkedIn Jobs').all().find(j => 
          j.json.id === job.jobId || j.json.title === job.title
        );

        items.push({
          json: {
            ...originalJob?.json,
            ...job,
            ai_filtered: true,
            filtered_at: new Date().toISOString()
          }
        });
      }
    }
  } catch (error) {
    console.error('Error parsing AI response:', error);
    continue;
  }
}

return items;

// Extract markdown from OpenAI response
for (const item of $input.all()) {
  let markdown = item.json.text || item.json.message?.content || item.json.output || '';

  // Remove code block markers if present
  markdown = markdown.replace(/```markdown\s*/g, '').replace(/```\s*$/g, '').trim();

  item.json.cover_letter_markdown = markdown;
}

return $input.all();

const item = $input.first();
const urls = (() => { try { return JSON.parse(item.json.email_search_urls || '[]'); } catch (error) { return []; } })();
const headers = {
  'User-Agent': $env.USER_AGENT || 'Mozilla/5.0 (compatible; JobApplicationBot/1.0; +https://example.com/bot)',
  'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'
};
const fetched = [];
for (const url of urls) {
  if (!url) {
    continue;
  }
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url,
      headers,
      timeout: 10000,
      followRedirect: true,
      maxRedirects: 3,
      returnFullResponse: true,
      rejectUnauthorized: false
    });
    const body = typeof response.body === 'string' ? response.body : JSON.stringify(response.body);
    fetched.push({
      url,
      status: response.statusCode || response.status || 200,
      content_preview: body.slice(0, 6000)
    });
  } catch (error) {
    fetched.push({
      url,
      status: error.statusCode || error.status || 0,
      error: error.message || 'Request failed'
    });
  }
}
item.json.email_search_urls = urls;
item.json.fetched_pages = fetched;
item.json.crawled_at = new Date().toISOString();
return [item];

const item = $input.first();
const domain = (item.json.company_domain || '').toLowerCase();
const pages = Array.isArray(item.json.fetched_pages) ? item.json.fetched_pages : [];
const emails = new Map();
if (domain) {
  const domainPattern = domain.replace(/\./g, '\\.');
  const regex = new RegExp(`[a-zA-Z0-9._%+-]+@${domainPattern}`, 'gi');
  for (const page of pages) {
    const content = page?.content_preview || '';
    let match;
    while ((match = regex.exec(content)) !== null) {
      const email = match[0].toLowerCase();
      if (!emails.has(email)) {
        emails.set(email, {
          email,
          source_url: page?.url || item.json.companyWebsite || '',
          source_status: page?.status || null,
          context_snippet: content.slice(Math.max(regex.lastIndex - 120, 0), regex.lastIndex + 120)
        });
      }
    }
  }
}
item.json.extracted_emails = Array.from(emails.values());
item.json.emails_found_count = item.json.extracted_emails.length;
item.json.extraction_regex_domain = domain;
return [item];

