const results = [];
for (const item of $input.all()) {
  const base = { ...item.json };
  const raw = base.text || base.message?.content || base.output || base.response || base.result || base;
  let parsed = null;
  if (typeof raw === 'string') {
    const jsonMatch = raw.match(/```json\s*([\s\S]*?)```/i);
    const payload = jsonMatch ? jsonMatch[1] : raw;
    try {
      parsed = JSON.parse(payload);
    } catch (error) {
      try {
        parsed = JSON.parse(raw);
      } catch (innerError) {
        parsed = null;
      }
    }
  } else if (raw && typeof raw === 'object') {
    parsed = raw;
  }
  const extractedEmails = base.extracted_emails || [];
  const best = parsed?.best_contact || (Array.isArray(parsed?.ranked_contacts) ? parsed.ranked_contacts[0] : null) || parsed || {};
  const email = (best?.email || '').toLowerCase();
  const firstName = best?.first_name || (best?.name ? best.name.split(' ')[0] : '') || '';
  const lastName = best?.last_name || (best?.name ? best.name.split(' ').slice(1).join(' ') : '');
  const confidence = typeof best?.confidence === 'number' ? best.confidence : (typeof best?.confidence_score === 'number' ? best.confidence_score : (email ? 0.75 : 0));
  const method = best?.method || (email ? 'found-on-page' : 'not-found');
  const sourceUrl = best?.source_url || (extractedEmails.find((entry) => entry.email === email)?.source_url) || base.normalized_company_website || base.companyWebsite || '';
  const formatted = {
    ...base,
    gpt_raw_response: parsed || raw || null,
    gpt_reasoning: parsed?.notes || parsed?.reason || best?.reason || '',
    ranked_contacts: Array.isArray(parsed?.ranked_contacts) ? parsed.ranked_contacts : [],
    email: email || '',
    first_name: firstName || '',
    last_name: lastName || '',
    contact_email: email || '',
    contact_first_name: firstName || (email ? 'Hiring Manager' : ''),
    contact_last_name: lastName || '',
    contact_title: best?.title || '',
    confidence_score: Math.max(0, Math.min(1, confidence || 0)),
    extraction_method: method,
    source_url: sourceUrl,
    needs_manual_contact: !email,
    needs_manual_review: confidence < 0.6,
    review_reason: confidence < 0.6 ? 'Low confidence score - verify before sending' : '',
    emails_found: extractedEmails
  };
  if (!formatted.contact_first_name) {
    formatted.contact_first_name = formatted.first_name || 'Hiring Manager';
  }
  if (!formatted.first_name) {
    formatted.first_name = formatted.contact_first_name || 'Hiring Manager';
  }
  if (!formatted.contact_title) {
    formatted.contact_title = email ? 'People Team' : '';
  }
  if (!formatted.review_reason) {
    delete formatted.review_reason;
  }
  results.push({ json: formatted });
}
return results;

const results = [];
for (const item of $input.all()) {
  const base = { ...item.json };
  const domain = (() => {
    if (base.company_domain) return base.company_domain.toLowerCase();
    const raw = (base.companyWebsite || '').replace(/^https?:\/\//, '');
    const parts = raw ? raw.split('/') : [];
    return (parts.length ? parts[0] : '').toLowerCase();
  })();
  const normalizedSite = base.normalized_company_website || (domain ? `https://${domain}` : '');
  const localPartCandidates = ['hr', 'people', 'talent', 'recruiting'];
  let inferredEmail = '';
  if (domain) {
    inferredEmail = `${localPartCandidates[0]}@${domain}`;
  }
  const fallback = {
    ...base,
    email: inferredEmail || '',
    contact_email: inferredEmail || '',
    contact_first_name: 'Hiring Manager',
    contact_last_name: '',
    contact_title: 'HR/People Team',
    confidence_score: inferredEmail ? 0.5 : 0,
    extraction_method: inferredEmail ? 'inferred-pattern' : 'not-found',
    source_url: normalizedSite || base.companyWebsite || '',
    needs_manual_contact: !inferredEmail,
    needs_manual_review: true,
    review_reason: inferredEmail ? 'Email inferred from company domain - verify before sending' : 'Email unavailable - manual lookup required',
    fallback_generated_at: new Date().toISOString()
  };
  if (!fallback.email) {
    fallback.email = '[EMAIL_NEEDED]';
    fallback.contact_email = '[EMAIL_NEEDED]';
  }
  if (!fallback.first_name) {
    fallback.first_name = 'Hiring Manager';
  }
  fallback.emails_found = base.emails_found || base.extracted_emails || [];
  results.push({ json: fallback });
}
return results;
